INSERT INTO feature VALUES('conditionals','effects','Conditionals',NULL,'implemented','ordinary',NULL,'`if c { t } else { e }` lowers to the case of its condition over the two booleans, the condition bound as a computation; `-> T` states the answer each branch is read at and the case is ascribed, so the conditional synthesises it where nothing states its type, `else if` nests a second test in the false branch, and an exit in a branch leaves the function.','surface-lowering surface-pretty','corpus/model/control/conditional.gandr corpus/model/control/eliminator-answers.gandr corpus/pathological/control/eliminator-answer-type-mismatch.gandr corpus/pathological/control/eliminator-answer-type-tail-rung-only.gandr corpus/ledger/syntax/if-expression.gandr','corpus/model/control/conditional.gandr',NULL);
